import React, { useId } from 'react';
import { StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';
import Svg, { Defs, LinearGradient, Rect, Stop } from 'react-native-svg';

import {
  DARK_SHARE_BAR_COLORS,
  shareBarFill,
  shareBarWidth,
  type ShareBarColors,
  type ShareBarLook,
} from './shareState';

/**
 * The progress bar of a share, in the look of Pearkit's `ProgressBar`: a thin rounded track
 * with an amber-to-green fill. This one is drawn with plain styles and react-native-svg only,
 * so an app that copies the piece needs nothing else, and it adds the two looks a share needs
 * beyond "moving": `holding` (waiting for the other side) and `stopped` (paused).
 */
export type ShareProgressBarProps = {
  /** 0 to 1. */
  value: number;
  look?: ShareBarLook;
  /** Thickness in points. */
  height?: number;
  colors?: ShareBarColors;
  style?: StyleProp<ViewStyle>;
  accessibilityLabel?: string;
};

export function ShareProgressBar({
  value,
  look = 'moving',
  height = 4,
  colors = DARK_SHARE_BAR_COLORS,
  style,
  accessibilityLabel,
}: ShareProgressBarProps) {
  const id = `pk-share-bar-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const part = shareBarWidth(value);
  const [from, to] = shareBarFill(look, colors);
  const radius = height / 2;
  return (
    <View
      accessibilityRole="progressbar"
      accessibilityLabel={accessibilityLabel}
      accessibilityValue={{ min: 0, max: 100, now: Math.round(part * 100) }}
      style={[styles.track, { height, borderRadius: radius, backgroundColor: colors.track }, style]}
    >
      {part > 0 ? (
        <View style={[styles.fill, { width: `${part * 100}%`, borderRadius: radius }]}>
          <Svg width="100%" height="100%" preserveAspectRatio="none" style={StyleSheet.absoluteFill}>
            <Defs>
              <LinearGradient id={id} x1="0" y1="0" x2="1" y2="0">
                <Stop offset={0} stopColor={from} stopOpacity={1} />
                <Stop offset={1} stopColor={to} stopOpacity={1} />
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" rx={radius} ry={radius} fill={`url(#${id})`} />
          </Svg>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  track: { width: '100%', overflow: 'hidden' },
  fill: { height: '100%', overflow: 'hidden' },
});
